"use strict";(globalThis.webpackChunkithelps=globalThis.webpackChunkithelps||[]).push([[518],{4369(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"publish-npm-package-to-sonatype-nexus","metadata":{"permalink":"/publish-npm-package-to-sonatype-nexus","source":"@site/blog/2025-04-01-publish-npm-package-to-sonatype-nexus/index.md","title":"\u041f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u044f npm \u043f\u0430\u043a\u0435\u0442\u0430 \u0432 Sonatype Nexus","description":"\u041f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u0434\u043b\u044f \u043f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u0438 npm-\u043f\u0430\u043a\u0435\u0442\u0430. \u0421\u043e\u0437\u0434\u0430\u043d\u0438\u0435 npm-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f \u0432 Nexus, \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f, \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 Realm.","date":"2025-04-01T00:00:00.000Z","tags":[{"inline":false,"label":"Nexus","permalink":"/tags/nexus"},{"inline":false,"label":"npm","permalink":"/tags/npm"}],"readingTime":4.67,"hasTruncateMarker":true,"authors":[],"frontMatter":{"tags":["nexus","npm"],"slug":"publish-npm-package-to-sonatype-nexus"},"unlisted":false,"nextItem":{"title":"\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 Sonatype Nexus \u0432 Docker-\u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0435","permalink":"/install-sonatype-nexus-in-docker-container"}},"content":"\u041f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u0434\u043b\u044f \u043f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u0438 npm-\u043f\u0430\u043a\u0435\u0442\u0430. \u0421\u043e\u0437\u0434\u0430\u043d\u0438\u0435 npm-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f \u0432 Nexus, \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f, \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 Realm.\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 \u0441\u0431\u043e\u0440\u043a\u0438 \u0432 Vite {#set-up-build-in-vite}\\n\\n\u041f\u0440\u0438\u043c\u0435\u0440 `vite.config.ts` \u0441 \u043f\u043b\u0430\u0433\u0438\u043d\u043e\u043c `vite-plugin-dts` \u0434\u043b\u044f \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0442\u0438\u043f\u043e\u0432 TS:\\n\\n```ts title=\\"vite.config.ts\\"\\nimport { defineConfig } from \'vite\';\\nimport react from \'@vitejs/plugin-react\';\\nimport dts from \'vite-plugin-dts\';\\n\\nexport default defineConfig({\\n  plugins: [\\n    react(),\\n    dts({\\n      rollupTypes: true,\\n      tsconfigPath: \'./tsconfig.app.json\',\\n    }),\\n  ],\\n  build: {\\n    lib: {\\n      entry: \'src/components/index.ts\',\\n      name: \'MyComponentLibrary\',\\n      fileName: (format, name) => `${name}.${format}.js`,\\n    },\\n    rollupOptions: {\\n      external: [\'react\', \'react-dom\', \'@mui/material\', \'@emotion/react\', \'@emotion/styled\'],\\n      output: {\\n        globals: {\\n          react: \'React\',\\n          \'react-dom\': \'ReactDOM\',\\n          \'@mui/material\': \'MaterialUI\',\\n          \'@emotion/react\': \'EmotionReact\',\\n          \'@emotion/styled\': \'EmotionStyled\',\\n        },\\n      },\\n    },\\n  },\\n});\\n```\\n\\n\u0411\u0430\u043d\u0434\u043b \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u043f\u043e\u043c\u0435\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u043f\u0430\u043f\u043a\u0443 `dist/`.\\n\\n\u0418\u043c\u044f \u0444\u0430\u0439\u043b\u0430 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f \u0432 \u043a\u043e\u043b\u043b\u0431\u044d\u043a\u0435 `build.lib.fileName` \u0438 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0438\u043c\u044f \u043c\u043e\u0434\u0443\u043b\u044f \u0438 \u0435\u0433\u043e \u0444\u043e\u0440\u043c\u0430\u0442:\\n- `es` \u2014 \u043c\u043e\u0434\u0443\u043b\u044c ES Modules;\\n- `umd` \u2014 \u043c\u043e\u0434\u0443\u043b\u044c CommonJS.\\n\\n## \u041e\u043f\u0438\u0441\u0430\u043d\u0438\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u0432 `package.json` {#project-package-json}\\n\\n```json title=\\"package.json\\"\\n{\\n  \\"name\\": \\"My project name\\",\\n  \\"version\\": \\"0.1.0\\",\\n  \\"description\\": \\"My project description\\",\\n  \\"type\\": \\"module\\",\\n  \\"main\\": \\"dist/index.umd.js\\",\\n  \\"module\\": \\"dist/index.es.js\\",\\n  \\"types\\": \\"dist/index.d.ts\\",\\n  \\"exports\\": {\\n    \\".\\": {\\n      \\"types\\": \\"./dist/index.d.ts\\",\\n      \\"import\\": \\"./dist/index.es.js\\",\\n      \\"require\\": \\"./dist/index.umd.js\\"\\n    }\\n  },\\n  \\"files\\": [\\n    \\"dist\\"\\n  ],\\n  \\"publishConfig\\": {\\n    \\"registry\\": \\"http://localhost:8081/repository/my-test-repo-hosted/\\"\\n  },\\n  \\"scripts\\": {\\n    \\"build\\": \\"tsc -b && vite build\\",\\n    \\"lint\\": \\"eslint .\\",\\n    \\"storybook\\": \\"storybook dev -p 6006\\",\\n    \\"build-storybook\\": \\"storybook build\\"\\n  },\\n  \\"devDependencies\\": {\\n    // ...\\n  },\\n  \\"peerDependencies\\": {\\n    \\"@emotion/react\\": \\"^11.0.0\\",\\n    \\"@emotion/styled\\": \\"^11.0.0\\",\\n    \\"@fontsource/roboto\\": \\"^5.1.1\\",\\n    \\"@mui/icons-material\\": \\"^6.4.0\\",\\n    \\"@mui/material\\": \\"^6.0.0\\",\\n    \\"react\\": \\">=18.0.0\\",\\n    \\"react-dom\\": \\">=18.0.0\\"\\n  },\\n  \\"eslintConfig\\": {\\n    \\"extends\\": [\\n      \\"plugin:storybook/recommended\\"\\n    ]\\n  }\\n}\\n```\\n\\n\u0417\u0434\u0435\u0441\u044c \u0432 \u043f\u043e\u043b\u0435 `exports` \u0432\u043e \u0432\u043b\u043e\u0436\u0435\u043d\u043d\u043e\u043c \u043f\u043e\u043b\u0435 `.`:\\n- `types` \u2014 \u043f\u0443\u0442\u044c \u043a \u0431\u0430\u043d\u0434\u043b\u0443 \u0441 \u0442\u0438\u043f\u0430\u043c\u0438;\\n- `import` \u2014 \u043f\u0443\u0442\u044c \u043a ES Modules \u0431\u0430\u043d\u0434\u043b\u0443;\\n- `require` \u2014 \u043f\u0443\u0442\u044c \u043a CommonJS \u0431\u0430\u043d\u0434\u043b\u0443.\\n\\n\u0412 \u043f\u043e\u043b\u0435 `publishConfig.registry` \u043f\u0440\u043e\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0430\u0434\u0440\u0435\u0441 npm hosted-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f \u0432 Nexus.\\n\\n## \u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 Sonatype Nexus {#set-up-sonatype-nexus}\\n\\n### 1. \u0423\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0438 \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u0442\u044c Nexus\\n\\n\u0420\u0430\u0437\u0432\u0435\u0440\u043d\u0443\u0442\u044c Sonatype Nexus \u0432 Docker-\u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0435 \u043f\u043e \u044d\u0442\u043e\u0439 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: [\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 Sonatype Nexus \u0432 Docker-\u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0435](../2025-02-24-install-sonatype-nexus-in-docker-container.md)\\n\\n### 2. \u0412\u043a\u043b\u044e\u0447\u0438\u0442\u044c Realm \u0434\u043b\u044f npm {#add-npm-realm}\\n\\n![Pasted image 20250401184417.png](./img/activate-nexus-realm.png)\\n\\n### 3. \u0421\u043e\u0437\u0434\u0430\u0442\u044c \u0440\u043e\u043b\u044c \u0434\u043b\u044f \u0447\u0442\u0435\u043d\u0438\u044f \u0438 \u0437\u0430\u043f\u0438\u0441\u0438 \u043f\u0430\u043a\u0435\u0442\u043e\u0432 \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 {#create-role}\\n\\n\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u0444\u043e\u0440\u043c\u0443 \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044f \u0440\u043e\u043b\u0438:\\n\\n- \u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b **Security** -> **Roles**\\n- \u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u043a \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044e \u0440\u043e\u043b\u0438 \u043a\u043d\u043e\u043f\u043a\u043e\u0439 **Create Role**\\n- \u0437\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u043e\u043b\u044f:\\n\\n![Pasted image 20250401185153.png](./img/create-nexus-user-role.png)\\n\\n\u041d\u0438\u0436\u0435 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 **Applied Privileges** \u0434\u043b\u044f \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u043f\u0440\u0438\u0432\u0438\u043b\u0435\u0433\u0438\u0439 \u043d\u0430\u0436\u0430\u0442\u044c **Modify Applied Privileges** \u0438 \u043e\u0442\u0444\u0438\u043b\u044c\u0442\u0440\u043e\u0432\u0430\u0442\u044c \u043e\u0442\u043a\u0440\u044b\u0432\u0448\u0438\u0439\u0441\u044f \u0441\u043f\u0438\u0441\u043e\u043a \u043f\u043e \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044e `npm`, \u043f\u043e\u0441\u043b\u0435 \u044d\u0442\u043e\u0433\u043e \u0432\u044b\u0431\u0440\u0430\u0442\u044c \u043f\u0440\u0438\u0432\u0438\u043b\u0435\u0433\u0438\u0438:\\n- `nx-repository-view-npm-*-browse`\\n- `nx-repository-view-npm-*-edit`\\n- `nx-repository-view-npm-*-read`\\n\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u043a\u043d\u043e\u043f\u043a\u043e\u0439 **Confirm**:\\n\\n![Pasted image 20250401190722.png](./img/modify-nexus-repo-applied-privileges.png)\\n\\n\u0420\u0430\u0437\u0434\u0435\u043b **Applied Roles** \u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043f\u0443\u0441\u0442\u044b\u043c:\\n\\n![Pasted image 20250401191109.png](./img/nexus-repo-applied-roles.png)\\n\\n\u0421\u043e\u0437\u0434\u0430\u0442\u044c \u0440\u043e\u043b\u044c \u043a\u043d\u043e\u043f\u043a\u043e\u0439 **Save**.\\n\\n### 4. \u0421\u043e\u0437\u0434\u0430\u0442\u044c \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f \u0434\u043b\u044f \u043f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u0438 \u043f\u0430\u043a\u0435\u0442\u0430 {#create-user}\\n\\n- \u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b **Security** -> **Users**\\n- \u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u043a \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044e \u0440\u043e\u043b\u0438 \u043a\u043d\u043e\u043f\u043a\u043e\u0439 **Create local user**\\n- \u0437\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u043e\u043b\u044f \u0441 \u0434\u0430\u043d\u043d\u044b\u043c\u0438 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f\\n- \u0432 \u043a\u043e\u043d\u0446\u0435 \u0444\u043e\u0440\u043c\u044b \u043f\u0435\u0440\u0435\u043c\u0435\u0441\u0442\u0438\u0442\u044c \u0440\u0430\u043d\u0435\u0435 \u0441\u043e\u0437\u0434\u0430\u043d\u043d\u0443\u044e \u0440\u043e\u043b\u044c \u0432 \u043f\u0440\u0430\u0432\u044b\u0439 \u0441\u0442\u043e\u043b\u0431\u0435\u0446 **Granted**\\n- \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f \u043a\u043d\u043e\u043f\u043a\u043e\u0439 **Create local user**\\n\\n![Pasted image 20250401191627.png](./img/create-nexus-local-user.png)\\n\\n### 5. \u0421\u043e\u0437\u0434\u0430\u0442\u044c \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 {#create-repositories}\\n\\n\u041d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e \u0441\u043e\u0437\u0434\u0430\u0442\u044c 3 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f: **proxy**, **hosted** \u0438 **group**:\\n\\n![Pasted image 20250401192125.png](./img/nexus-repositories-scheme.png)\\n\\n\u0414\u043b\u044f \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0438\u0437 \u043d\u0438\u0445 \u043d\u0443\u0436\u043d\u043e:\\n\\n- \u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b **Repository** -> **Repositories**\\n- \u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u043a \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044e \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f \u043a\u043d\u043e\u043f\u043a\u043e\u0439 **Create repository**.\\n\\n#### Proxy-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 {#create-proxy-repository}\\n\\n\u0412 \u043e\u0442\u043a\u0440\u044b\u0432\u0448\u0435\u043c\u0441\u044f \u0441\u043f\u0438\u0441\u043a\u0435 **Recipe** \u0432\u044b\u0431\u0440\u0430\u0442\u044c `npm (proxy)` \u0438 \u0437\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u043e\u043b\u044f:\\n\\n- **Name** - \u043f\u0440\u0435\u0434\u043f\u043e\u0447\u0438\u0442\u0430\u0435\u043c\u043e\u0435 \u0438\u043c\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f (\u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0432 \u043a\u043e\u043d\u0446\u0435 \\"proxy\\" \u0434\u043b\u044f \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438);\\n- **Remote storage** - \u0430\u0434\u0440\u0435\u0441 \u0443\u0434\u0430\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f \u0441 \u043f\u0430\u043a\u0435\u0442\u0430\u043c\u0438 (\u0432\u0432\u0435\u0441\u0442\u0438 \u0430\u0434\u0440\u0435\u0441 \u043e\u0431\u0449\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0433\u043e `https://registry.npmjs.org`).\\n\\n\u041e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u043f\u043e\u043b\u044f \u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0438 \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 \u043a\u043d\u043e\u043f\u043a\u043e\u0439 **Create repository**:\\n\\n![Pasted image 20250401193011.png](./img/create-npm-proxy-repository-settings.png)\\n\\n#### Hosted-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 {#create-hosted-repository}\\n\\n\u0412 \u043e\u0442\u043a\u0440\u044b\u0432\u0448\u0435\u043c\u0441\u044f \u0441\u043f\u0438\u0441\u043a\u0435 **Recipe** \u0432\u044b\u0431\u0440\u0430\u0442\u044c `npm (hosted)` \u0438 \u0437\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u043e\u043b\u044f:\\n\\n- **Name** - \u043f\u0440\u0435\u0434\u043f\u043e\u0447\u0438\u0442\u0430\u0435\u043c\u043e\u0435 \u0438\u043c\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f (\u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0432 \u043a\u043e\u043d\u0446\u0435 \\"hosted\\" \u0434\u043b\u044f \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438);\\n- **Deployment policy** - \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0433\u043e \u0434\u0435\u043f\u043b\u043e\u044f \u043e\u0434\u043d\u043e\u0439 \u0438 \u0442\u043e\u0439 \u0436\u0435 \u0432\u0435\u0440\u0441\u0438\u0438.\\n\\n\u041e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u043f\u043e\u043b\u044f \u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0438 \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 \u043a\u043d\u043e\u043f\u043a\u043e\u0439 **Create repository**:\\n\\n![Pasted image 20250401193157.png](./img/create-npm-hosted-repository-settings.png)\\n\\n#### Group-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 {#create-group-repository}\\n\\n\u0412 \u043e\u0442\u043a\u0440\u044b\u0432\u0448\u0435\u043c\u0441\u044f \u0441\u043f\u0438\u0441\u043a\u0435 **Recipe** \u0432\u044b\u0431\u0440\u0430\u0442\u044c `npm (group)` \u0438 \u0437\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043f\u043e\u043b\u044f:\\n\\n- **Name** - \u043f\u0440\u0435\u0434\u043f\u043e\u0447\u0438\u0442\u0430\u0435\u043c\u043e\u0435 \u0438\u043c\u044f \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f (\u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0432 \u043a\u043e\u043d\u0446\u0435 \\"group\\" \u0434\u043b\u044f \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438);\\n- **Member repositories** - \u0441\u043f\u0438\u0441\u043e\u043a \u0441\u0433\u0440\u0443\u043f\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0435\u0432, \u043f\u0435\u0440\u0435\u0442\u0430\u0449\u0438\u0442\u044c \u0432 \u043f\u0440\u0430\u0432\u044b\u0439 \u0441\u0442\u043e\u043b\u0431\u0435\u0446 **Members** \u0442\u043e\u043b\u044c\u043a\u043e \u0447\u0442\u043e \u0441\u043e\u0437\u0434\u0430\u043d\u043d\u044b\u0435 proxy \u0438 hosted \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438.\\n\\n\u041e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u043f\u043e\u043b\u044f \u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0438 \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 \u043a\u043d\u043e\u043f\u043a\u043e\u0439 **Create repository**:\\n\\n![Pasted image 20250401194002.png](./img/create-npm-group-repository-settings.png)\\n\\n### 6. \u0410\u0432\u0442\u043e\u0440\u0438\u0437\u0430\u0446\u0438\u044f \u0432 npm-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 {#npm-repository-login}\\n\\n\u0414\u043b\u044f \u0430\u0432\u0442\u043e\u0440\u0438\u0437\u0430\u0446\u0438\u0438 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043a\u043e\u043c\u0430\u043d\u0434\u0443 \u0432\u0438\u0434\u0430:\\n\\n`npm login --registry=[\u0430\u0434\u0440\u0435\u0441-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f]/repository/[\u0438\u043c\u044f-hosted-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f]/`\\n\\n**\u0412\u043d\u0438\u043c\u0430\u043d\u0438\u0435!!!** \u0412\u0430\u0436\u043d\u043e \u043d\u0430\u043b\u0438\u0447\u0438\u0435 \u0441\u043b\u044d\u0448\u0430 `/` \u0432 \u043a\u043e\u043d\u0446\u0435 \u043a\u043e\u043c\u0430\u043d\u0434\u044b \u043f\u043e\u0441\u043b\u0435 \u0438\u043c\u0435\u043d\u0438 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f. \u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0434\u043b\u044f \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e \u0440\u0430\u0437\u0432\u0435\u0440\u043d\u0443\u0442\u043e\u0433\u043e Nexus:\\n\\n```shell\\nnpm login --registry=http://localhost:8081/repository/my-test-repo-hosted/\\n```\\n\\n\u0423\u0447\u0435\u0442\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0435\u0432 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f \u0432 \u0444\u0430\u0439\u043b\u0435 `.npmrc`. \u041f\u043e\u0441\u043b\u0435 \u0430\u0432\u0442\u043e\u0440\u0438\u0437\u0430\u0446\u0438\u0438 \u0432 \u0444\u0430\u0439\u043b\u0435 \u043f\u043e\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u0432\u0438\u0434\u0430:\\n\\n`//[\u0430\u0434\u0440\u0435\u0441-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f]/repository/[\u0438\u043c\u044f-hosted-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f]/:_authToken=NpmToken.xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx`\\n\\n![Pasted image 20250401200415.png](./img/npmrc-nexus-repo-settings.png)\\n\\n\u0412 \u0441\u043b\u0443\u0447\u0430\u0435 \u043f\u0440\u043e\u0431\u043b\u0435\u043c \u0441 \u0430\u0432\u0442\u043e\u0440\u0438\u0437\u0430\u0446\u0438\u0435\u0439 \u0443\u0434\u0430\u043b\u0438\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443 \u0438\u0437 \u0444\u0430\u0439\u043b\u0430 `.npmrc` \u0438 \u0430\u0432\u0442\u043e\u0440\u0438\u0437\u043e\u0432\u0430\u0442\u044c\u0441\u044f \u0437\u0430\u043d\u043e\u0432\u043e.\\n\\n### 7. \u041f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u0430\u043a\u0435\u0442\u0430 \u0432 npm-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 {#publish-package-to-npm-repository}\\n\\n\u0414\u043b\u044f \u043f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u0438 \u043f\u0430\u043a\u0435\u0442\u0430 \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u0441\u0431\u043e\u0440\u043a\u0443 \u0431\u0430\u043d\u0434\u043b\u0430:\\n\\n```shell\\nnpm run build\\n```\\n\\n\u041f\u043e\u0441\u043b\u0435 \u0441\u0431\u043e\u0440\u043a\u0438 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u0438\u0437 \u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440\u0438\u0438 \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u043a\u043e\u043c\u0430\u043d\u0434\u0443:\\n\\n```shell\\nnpm publish\\n```\\n\\n\u041f\u0440\u0438 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0438 \u0442\u0430\u043a\u043e\u0439 \u043a\u043e\u043c\u0430\u043d\u0434\u044b \u0431\u0435\u0437 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 \u043f\u0430\u043a\u0435\u0442 \u0431\u0443\u0434\u0435\u0442 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d \u0432 **hosted**-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439, \u0443\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u0439 \u0432 \u043f\u043e\u043b\u0435 `publishConfig.registry` \u0444\u0430\u0439\u043b\u0430 `package.json` (\u0441\u043c. \u043f\u0440\u0438\u043c\u0435\u0440 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 [**\u041e\u043f\u0438\u0441\u0430\u043d\u0438\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u0432 `package.json`**](#project-package-json)).\\n\\n\u0410\u0434\u0440\u0435\u0441 **hosted**-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f \u0434\u043b\u044f \u043f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u0438 \u043c\u043e\u0436\u043d\u043e \u0443\u043a\u0430\u0437\u0430\u0442\u044c \u044f\u0432\u043d\u043e, \u0434\u043e\u0431\u0430\u0432\u0438\u0432 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 `--registry` (\u043d\u0435 \u0437\u0430\u0431\u044b\u0442\u044c \u0441\u043b\u044d\u0448 `/` \u0432 \u043a\u043e\u043d\u0446\u0435 \u043f\u043e\u0441\u043b\u0435 \u0438\u043c\u0435\u043d\u0438 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f):\\n\\n```shell\\nnpm publish --registry=http://localhost:8081/repository/my-test-repo-hosted/\\n```\\n\\n### 8. \u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u043f\u0430\u043a\u0435\u0442\u0430 \u0432 \u0434\u0440\u0443\u0433\u043e\u043c \u043f\u0440\u043e\u0435\u043a\u0442\u0435 \u0438\u0437 group-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f Nexus {#install-package-from-repository}\\n\\n\u0414\u043b\u044f \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 \u043f\u0430\u043a\u0435\u0442\u0430 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e \u044f\u0432\u043d\u043e \u0443\u043a\u0430\u0437\u0430\u0442\u044c \u0430\u0434\u0440\u0435\u0441 **group**-\u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f \u0441 \u043f\u043e\u043c\u043e\u0449\u044c\u044e \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0430 `--registry` (\u043d\u0435 \u0437\u0430\u0431\u044b\u0442\u044c \u0441\u043b\u044d\u0448 `/` \u0432 \u043a\u043e\u043d\u0446\u0435 \u043f\u043e\u0441\u043b\u0435 \u0438\u043c\u0435\u043d\u0438 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f):\\n\\n```shell\\nnpm install my-component-library@0.1.0 --registry http://localhost:8081/repository/my-test-repo-group/\\n```"},{"id":"install-sonatype-nexus-in-docker-container","metadata":{"permalink":"/install-sonatype-nexus-in-docker-container","source":"@site/blog/2025-02-24-install-sonatype-nexus-in-docker-container.md","title":"\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 Sonatype Nexus \u0432 Docker-\u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0435","description":"\u0417\u0430\u043f\u0443\u0441\u043a Docker-\u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0430 \u0438 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a \u0432\u0435\u0431-\u0438\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0443 Sonatype Nexus.","date":"2025-02-24T00:00:00.000Z","tags":[{"inline":false,"label":"Nexus","permalink":"/tags/nexus"}],"readingTime":1.08,"hasTruncateMarker":true,"authors":[],"frontMatter":{"tags":["nexus"],"slug":"install-sonatype-nexus-in-docker-container"},"unlisted":false,"prevItem":{"title":"\u041f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u044f npm \u043f\u0430\u043a\u0435\u0442\u0430 \u0432 Sonatype Nexus","permalink":"/publish-npm-package-to-sonatype-nexus"}},"content":"\u0417\u0430\u043f\u0443\u0441\u043a Docker-\u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0430 \u0438 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a \u0432\u0435\u0431-\u0438\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0443 Sonatype Nexus.\\n\\n\x3c!-- truncate --\x3e\\n\\n## 1. \u0417\u0430\u0433\u0440\u0443\u0437\u043a\u0430 \u043e\u0431\u0440\u0430\u0437\u0430 Nexus (\u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e) {#pull-nexus-image}\\n\\n\u041e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u044e\u044e \u0432\u0435\u0440\u0441\u0438\u044e \u043e\u0431\u0440\u0430\u0437\u0430 Sonatype Nexus 3:\\n\\n```sh\\ndocker pull sonatype/nexus3\\n```\\n\\n## 2. \u0417\u0430\u043f\u0443\u0441\u043a \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0430 Nexus {#run-nexus-container}\\n\\n```sh\\ndocker run -d --name nexus -p 8081:8081 -v nexus-data:/nexus-data sonatype/nexus3\\n```\\n\\n- `docker run` \u2014 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u043d\u043e\u0432\u044b\u0439 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440.\\n- `-d` \u2014 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440 \u0432 \u0444\u043e\u043d\u043e\u0432\u043e\u043c \u0440\u0435\u0436\u0438\u043c\u0435 (detached mode).\\n- `--name nexus` \u2014 \u0437\u0430\u0434\u0430\u0451\u0442 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0443 \u0438\u043c\u044f `nexus`.\\n- `-p 8081:8081` \u2014 \u043f\u0440\u043e\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u043f\u043e\u0440\u0442 `8081` \u0445\u043e\u0441\u0442\u0430 \u043d\u0430 \u043f\u043e\u0440\u0442 `8081` \u0432\u043d\u0443\u0442\u0440\u0438 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0430. \u042d\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u0434\u043e\u0441\u0442\u0443\u043f \u043a Nexus \u043f\u043e \u0430\u0434\u0440\u0435\u0441\u0443 `http://localhost:8081`.\\n- `-v nexus-data:/nexus-data` \u2014 \u0441\u043e\u0437\u0434\u0430\u0451\u0442 Docker-\u0442\u043e\u043c \u0441 \u0438\u043c\u0435\u043d\u0435\u043c `nexus-data` \u0434\u043b\u044f \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u0434\u0430\u043d\u043d\u044b\u0445 Nexus (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0435\u0432 \u0438 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0439). \u042d\u0442\u043e \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u0443\u0435\u0442 \u0441\u043e\u0445\u0440\u0430\u043d\u043d\u043e\u0441\u0442\u044c \u0434\u0430\u043d\u043d\u044b\u0445 \u0434\u0430\u0436\u0435 \u043f\u0440\u0438 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0435 \u0438\u043b\u0438 \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0438 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0430.\\n- `sonatype/nexus3` \u2014 \u0443\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 Docker-\u043e\u0431\u0440\u0430\u0437, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0431\u0443\u0434\u0435\u0442 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c\u0441\u044f (Sonatype Nexus 3).\\n\\n## 3. \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440 \u0437\u0430\u043f\u0443\u0449\u0435\u043d {#verify-container-is-running}\\n\\n```sh\\ndocker ps\\n```\\n\\n\u0412 \u0441\u043f\u0438\u0441\u043a\u0435 \u0434\u043e\u043b\u0436\u0435\u043d \u043f\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440 \u0441 \u0438\u043c\u0435\u043d\u0435\u043c `nexus`.\\n\\n## 4. \u0414\u043e\u0441\u0442\u0443\u043f \u043a Nexus {#access-nexus}\\n\\n\u041f\u043e\u0441\u043b\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0430 \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 \u0438 \u043f\u0435\u0440\u0435\u0439\u0434\u0438\u0442\u0435 \u043f\u043e \u0430\u0434\u0440\u0435\u0441\u0443:\\n\\n```\\nhttp://localhost:8081\\n```\\n\\n\u041e\u0442\u043a\u0440\u043e\u0435\u0442\u0441\u044f \u0438\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441 Nexus Repository Manager.\\n\\n## 5. \u0423\u0447\u0435\u0442\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e {#default-credentials}\\n\\n\u041f\u0440\u0438 \u043f\u0435\u0440\u0432\u043e\u043c \u0434\u043e\u0441\u0442\u0443\u043f\u0435 \u043a Nexus \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u0432\u0445\u043e\u0434. \u041f\u0430\u0440\u043e\u043b\u044c \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0442\u043e\u0440\u0430 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u043c \u043e\u0431\u0440\u0430\u0437\u043e\u043c \u0438 \u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0432 Docker-\u0442\u043e\u043c\u0435 `nexus-data` \u0432 \u0444\u0430\u0439\u043b\u0435 `/nexus-data/admin.password`."}]}}')}}]);